impl PltWarnPitchstab {
    pub const fn new() -> Self {
        Self(Led::new())
    }
    pub const fn is_on(&self) -> bool {
        self.0.is_on()
    }
}
impl Default for PltWarnPitchstab {
    fn default() -> Self {
        Self::new()
    }
}
impl Control for PltWarnPitchstab {
    fn accept(&mut self, packet: Packet<'_>) {
        self.0.accept(packet);
    }
    fn commit(&mut self) -> bool {
        self.0.commit()
    }
}

